mapper.insert:


    SELECT COALESCE(MAX(SPND_NUMB), 0) + 1
      FROM TH_USSPND

INSERT /* setUserSuspension */
  INTO TH_USSPND (
       SPND_NUMB
     , USER_NUMB
     , PREV_STAT
     , SPND_TYPE
     , SPND_RSON
     , SPND_CNTN
     , SPND_STAT
     , SYNC_STAT
     , STRT_DATE
     , ENDX_DATE
     , REGI_ADMN
     , REGI_DATE
     , UPDT_ADMN
     , UPDT_DATE
) VALUES (
       #{spndNumb}
     , #{userNumb}
     , #{prevStat}
     , #{spndType}
     , #{spndRson}
     , #{spndCntn,jdbcType=VARCHAR}
     , #{spndStat}
     , #{syncStat}
     , #{strtDate}
     , #{endxDate,jdbcType=TIMESTAMP}
     , #{regiAdmn}
     , CURRENT_TIMESTAMP
     , #{updtAdmn}
     , CURRENT_TIMESTAMP
)

mapper.update:
UPDATE /* uptUserSuspensionReleased */
       TH_USSPND
   SET SPND_STAT = 'RELEASED'
     , RLES_DATE = CURRENT_TIMESTAMP
     , RLES_CNTN = #{rlesCntn,jdbcType=VARCHAR}
     , RLES_ADMN = #{rlesAdmn}
     , UPDT_ADMN = #{updtAdmn}
     , UPDT_DATE = CURRENT_TIMESTAMP
 WHERE SPND_NUMB = #{spndNumb}
   AND USER_NUMB = #{userNumb}
   AND SPND_STAT = 'ACTIVE'

UPDATE /* uptUserStatusAfterSuspend */
       TM_USERXM
   SET USER_STAT = #{userStat}
 WHERE USER_NUMB = #{userNumb}
   AND USER_STAT = 'SUSPENDED'


UPDATE /* uptUserSuspSyncPending */
       TH_USSPND
   SET SYNC_STAT = #{userStatusSyncPending}
 WHERE SPND_NUMB = #{spndNumb}

